-- Rollback script generated by database-diff on <time>
-- Source (the sync script's model):  <server> / ddtest_edge_src
-- Target (will be changed back):     <server> / ddtest_edge_tgt
--
-- Running this on the TARGET database after the sync script of the same comparison puts its
-- schema back as it was read during the comparison. REVIEW IT BEFORE RUNNING.
-- - Nothing in this file has been executed by database-diff.
-- - It assumes the target changed only through the sync script since the comparison.
-- - Procedures, views, functions, triggers, synonyms, indexes and constraints the sync script
--   created are dropped first, with IF EXISTS so a sync script that stopped part way is fine.
-- - Tables, columns, sequences, types and schemas it created are commented out at the end:
--   dropping them loses the data written since.
-- - Changed objects get their earlier definition back. ALTER COLUMN statements are active:
--   check them for data loss (narrower types, NOT NULL).
-- - Objects only in the target are not here: the sync script leaves them (its drops are
--   commented out). Schemas it created only when missing are left in place.
-- - Only a backup brings back dropped data.
-- - Objects are ordered by kind, not by dependency; rerun a failed part after the rest.
-- - Uses CREATE OR ALTER and DROP IF EXISTS: SQL Server 2016 SP1 or later on the target.
USE [ddtest_edge_tgt];
GO
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

-- ==========================================================================================
-- User-defined types
-- ==========================================================================================
-- Type dbo.IdList differs: Spec: source (Id int NOT NULL), target (Id bigint NOT NULL)
-- A type cannot be altered: drop the objects that use it, DROP TYPE, CREATE TYPE, then recreate them.

-- ==========================================================================================
-- Columns
-- ==========================================================================================
-- dbo.Items.Status: Default: source (N'รอดำเนินการ'), target (N'เสร็จแล้ว')
DECLARE @default sysname, @drop nvarchar(max);
SELECT @default = dc.name FROM sys.default_constraints dc JOIN sys.columns c ON c.object_id = dc.parent_object_id AND c.column_id = dc.parent_column_id WHERE dc.parent_object_id = OBJECT_ID(N'[dbo].[Items]') AND c.name = N'Status';
IF @default IS NOT NULL BEGIN SET @drop = N'ALTER TABLE [dbo].[Items] DROP CONSTRAINT ' + QUOTENAME(@default); EXEC (@drop); END
ALTER TABLE [dbo].[Items] ADD DEFAULT (N'เสร็จแล้ว') FOR [Status];
GO
-- dbo.Items.Total: Type: source decimal(21,2), target decimal(23,2) Computed: source ([Qty]*[Price]), target (([Qty]*[Price])*(1))
-- IDENTITY or computed definition differs: SQL Server cannot ALTER this; rebuild the column or table manually.
GO

-- ==========================================================================================
-- Indexes, primary keys and unique constraints
-- ==========================================================================================
-- dbo.Items (primary key): Name: source (system-named), target PK_Items
-- Primary key differs. Foreign keys that reference it must be dropped first, so this is left commented out:
-- ALTER TABLE [dbo].[Items] DROP CONSTRAINT [PK__Items__<id>];
-- ALTER TABLE [dbo].[Items] ADD CONSTRAINT [PK_Items] PRIMARY KEY CLUSTERED ([ID]);
GO
-- dbo.Items.IX_Items_Title: Filter: source ([Title] IS NOT NULL), target (none)
DROP INDEX [IX_Items_Title] ON [dbo].[Items];
CREATE NONCLUSTERED INDEX [IX_Items_Title] ON [dbo].[Items] ([Title]);
GO

-- ==========================================================================================
-- Check constraints
-- ==========================================================================================
-- dbo.Items.CK_Items_Code: State: source ENABLED, target DISABLED
ALTER TABLE [dbo].[Items] DROP CONSTRAINT [CK_Items_Code];
ALTER TABLE [dbo].[Items] WITH CHECK ADD CONSTRAINT [CK_Items_Code] CHECK (len([Code])>(0));
ALTER TABLE [dbo].[Items] NOCHECK CONSTRAINT [CK_Items_Code];
GO

